class Editor:
    def __getstate__(self):                # what the memento captures
        return {"text": self._text, "caret": self._caret}

    def save(self) -> bytes:
        return pickle.dumps(self, protocol=pickle.HIGHEST_PROTOCOL)

    def restore(self, blob: bytes) -> None:
        self.__dict__.update(vars(pickle.loads(blob)))
